Script:
RejectedOffers = {
    states: [script[TransactionStates]],

    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=RejecedOffers]");
        api.addToMetaCache([
            {
                "Name": "B2B",
                "Types": [
                    [meta[B2B/Offer]]
                ]
            }
        ]);
        var dataSource = await model.getDatasource({
            endpoint: "B2B/Offer", 
            odataAppend: "/FromSystem(SystemId='" + app.Config.B2B.TransactionSource + "')?$filter=FunderState eq 'RejectedCancelled'",
			sort: [ 
				{ field: "EarliestRelatedTaxPoint", dir: "asc" }
			],
			pageSize: 1000
        });
        (await [script[RejectOffersGrid]]({element: container, dataSource: dataSource})).init();
    }
};
